def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Endgame: defect in the last 5 rounds
    if n >= 95:
        return 'D'

    # First few rounds: cooperate
    if n < 3:
        return 'C'

    my_moves = [h[0] for h in history]
    opp_moves = [h[1] for h in history]
    opp_defects = sum(1 for x in opp_moves if x == 'D')

    # If opponent is highly defective, defect
    if opp_defects > n * 0.5:
        return 'D'

    last_opp = opp_moves[-1]

    if last_opp == 'D':
        # Forgive if opponent has been mostly cooperative
        if opp_defects <= n * 0.2 and n > 10:
            return 'C'
        # If we just defected, try to break a mutual defection spiral
        last_my = my_moves[-1]
        if last_my == 'D' and opp_defects <= n * 0.4:
            return 'C'
        return 'D'
    else:
        return 'C'
